#ifndef DECODING_FILE_H
#define DECODING_FILE_H
#include <array>
#include <cstdint>
constexpr uint64_t n = 50;
constexpr uint64_t k = 20;
constexpr uint64_t w = 10;
constexpr uint64_t q = 4;
constexpr const char *s_gf4 = "322232133222133300010111001300";
constexpr const char *kekw_solution = "13000000000300300003000000000002010000110000030000";
// NOTE: H = [I | M^T] row by row: n-k rows of n symbols
constexpr const char *h_rows = "";
// load with `mzd_t *A = mzd_from_str(k, n, h)`

/// \tparam rows number of rows of the input
/// \tparam cols number of columns of the input
/// \param in matrix as a string, row by row
/// \return zero terminated string of the transposed matrix, as expected by
/// 	`ISDInstance::from_string` (H^T, like the decodingchallenge.org challenges)
template<const uint64_t rows, const uint64_t cols>
constexpr std::array<char, rows*cols + 1> transpose_string(const char *in) noexcept {
	std::array<char, rows*cols + 1> ret{};
	for (uint64_t i = 0; i < rows; ++i) {
		for (uint64_t j = 0; j < cols; ++j) {
			ret[j*rows + i] = in[i*cols + j];
		}
	}
	ret[rows*cols] = '\0';
	return ret;
}

constexpr auto h_matrix = transpose_string<n - k, n>(h_rows);
constexpr const char *h = h_matrix.data();

// NOTE: `s_gf4` is over GF(4), the library computes in Z/4Z: s = H*e mod q
constexpr auto s_matrix = [](){
	std::array<char, n - k + 1> ret{};
	for (uint64_t i = 0; i < n - k; ++i) {
		uint64_t v = 0;
		for (uint64_t j = 0; j < n; ++j) {
			v += uint64_t(h_rows[i*n + j] - '0') * uint64_t(kekw_solution[j] - '0');
		}
		ret[i] = char('0' + (v % q));
	}
	ret[n - k] = '\0';
	return ret;
}();
constexpr const char *s = s_matrix.data();
#endif //SECODING_FILE_H